// Adversarial preservation fixtures. These are generated bytes, not user media.
import { TagLib } from "taglib-wasm";
import { applyTagsToFile } from "taglib-wasm/simple";
import { readFile, writeFile, mkdir, copyFile } from "node:fs/promises";
import path from "node:path";
import {
  generated,
  fixture,
  independent,
  sha,
  packets,
  pcm,
  ffmpeg,
} from "./lab.mjs";
const backend =
  process.argv.find((x) => x.startsWith("--backend="))?.split("=")[1] ?? "wasi";
const t = await TagLib.initialize({ forceWasmType: backend });
const assetsJpeg = new Uint8Array(
  await readFile(path.join(generated, "assets", "new.jpg")),
);
const dir = path.join(generated, `edges-${backend}`);
await mkdir(dir, { recursive: true });
const results = { backend, version: t.version(), cases: [] };
async function edit(file, fn, buffer = false) {
  await fixture(file);
  const f = await t.open(buffer ? new Uint8Array(await readFile(file)) : file, {
    partial: false,
  });
  try {
    fn(f);
    if (buffer) {
      if (!f.save()) throw Error("save false");
      await writeFile(file, f.getFileBuffer());
    } else await f.saveToFile();
  } finally {
    f.dispose();
  }
}
function ss(n) {
  return Buffer.from([
    (n >>> 21) & 127,
    (n >>> 14) & 127,
    (n >>> 7) & 127,
    n & 127,
  ]);
}
function unss(b) {
  return (b[0] << 21) | (b[1] << 14) | (b[2] << 7) | b[3];
}
function frame(id, data, version = 4, flags = 0) {
  const h = Buffer.alloc(10);
  h.write(id);
  if (version === 4) ss(data.length).copy(h, 4);
  else h.writeUInt32BE(data.length, 4);
  h.writeUInt16BE(flags, 8);
  return Buffer.concat([h, data]);
}
function rawFrames(data) {
  if (data.subarray(0, 3).toString() !== "ID3") return [];
  const version = data[3],
    end = 10 + unss(data.subarray(6, 10)),
    frames = [];
  for (let i = 10; i + 10 <= end;) {
    const id = data.subarray(i, i + 4).toString();
    if (!/^[A-Z0-9]{4}$/.test(id)) break;
    const n =
      version === 4
        ? unss(data.subarray(i + 4, i + 8))
        : data.readUInt32BE(i + 4);
    const body = data.subarray(i + 10, i + 10 + n);
    frames.push({
      id,
      flags: data.readUInt16BE(i + 8),
      hash: sha(body),
      bytes: [...body],
    });
    i += n + 10;
  }
  return frames;
}
function injectId3(data) {
  const version = data[3],
    length = unss(data.subarray(6, 10));
  const comment = (lang, desc, text) =>
    frame(
      "COMM",
      Buffer.concat([Buffer.from([0]), Buffer.from(lang + desc + "\0" + text)]),
      version,
    );
  const extra = Buffer.concat([
    frame(
      "XZZZ",
      Buffer.from([0, 1, 254, 42]),
      version,
      version === 4 ? 0x1000 : 0x2000,
    ),
    frame("PRIV", Buffer.from("org.rhythm.lab\0private-bytes"), version),
    comment("eng", "English description", "English custom comment"),
    comment("por", "Other description", "Other custom comment"),
  ]);
  const h = Buffer.from(data.subarray(0, 10));
  ss(length + extra.length).copy(h, 6);
  return Buffer.concat([h, extra, data.subarray(10)]);
}
const nativeComments = (m) =>
  Object.values(m.native)
    .flat()
    .filter((x) => /COMM|COMMENT|DESCRIPTION|ANNO/.test(x.id));
const nativeCustom = (m) =>
  Object.values(m.native)
    .flat()
    .filter((x) =>
      /RHYTHM|MiXeD|PRIV|XZZZ|replaygain|REPLAYGAIN|COPYRIGHT|TCOP|cprt|LYRICS|USLT|©lyr/.test(
        x.id,
      ),
    );
const pictureHeaders = (m) =>
  Object.values(m.native)
    .flat()
    .filter((x) => x.id === "METADATA_BLOCK_PICTURE")
    .map((x) => ({ ...x.value, data: sha(x.value.data) }));
async function test(name, file, fn, options = {}) {
  const beforeBytes = await readFile(file),
    before = await independent(file),
    audio = packets(file),
    decoded = pcm(file);
  const r = {
    name,
    beforeComments: nativeComments(before),
    beforeCustom: nativeCustom(before),
    beforeRaw: rawFrames(beforeBytes),
    beforeVersion: beforeBytes[3],
    ...options,
  };
  r.beforePictureHeaders = pictureHeaders(before);
  if (options.marker)
    r.markerPresentBefore = beforeBytes.includes(Buffer.from(options.marker));
  results.cases.push(r);
  try {
    await fn();
    const afterBytes = await readFile(file),
      after = await independent(file);
    r.afterComments = nativeComments(after);
    r.afterCustom = nativeCustom(after);
    r.afterRaw = rawFrames(afterBytes);
    r.afterVersion = afterBytes[3];
    r.afterPictureHeaders = pictureHeaders(after);
    r.commentsUnchanged =
      JSON.stringify(r.beforeComments) === JSON.stringify(r.afterComments);
    r.customUnchanged =
      JSON.stringify(r.beforeCustom) === JSON.stringify(r.afterCustom);
    r.packetsUnchanged =
      JSON.stringify(audio) === JSON.stringify(packets(file));
    r.pcmUnchanged = decoded === pcm(file);
    r.title = after.common.title;
    if (options.marker)
      r.markerRetained = afterBytes.includes(Buffer.from(options.marker));
    console.log(
      backend,
      name,
      JSON.stringify({
        comments: r.commentsUnchanged,
        custom: r.customUnchanged,
        packets: r.packetsUnchanged,
        pcm: r.pcmUnchanged,
        marker: r.markerRetained,
      }),
    );
  } catch (e) {
    r.error = String(e);
  }
}
for (const version of [3, 4]) {
  const master = path.join(dir, `edge-v${version}.mp3`);
  ffmpeg([
    "-y",
    "-i",
    path.join(generated, "originals", "sine.mp3"),
    "-c:a",
    "copy",
    "-id3v2_version",
    String(version),
    "-write_id3v1",
    "0",
    master,
  ]);
  await writeFile(master, injectId3(await readFile(master)));
  for (const strategy of ["path", "buffer", "simple"]) {
    const file = path.join(dir, `v${version}-${strategy}.mp3`);
    await copyFile(master, file);
    await test(
      `mp3-v${version}-${strategy}-title`,
      file,
      () =>
        strategy === "simple"
          ? applyTagsToFile(file, { title: "Simple only-title" })
          : edit(
              file,
              (f) => f.setProperty("TITLE", "Core only-title"),
              strategy === "buffer",
            ),
      {
        strategyBackend:
          strategy === "simple" ? "auto (WASI on this host)" : backend,
      },
    );
  }
}
for (const ext of ["mp3", "flac", "m4a"]) {
  const master = path.join(generated, `node-${backend}`, `base.${ext}`);
  for (const mode of ["title", "clear-comment", "full-property-replacement"]) {
    const file = path.join(dir, `${ext}-${mode}.${ext}`);
    await copyFile(master, file);
    await test(`${ext}-${mode}`, file, () =>
      edit(file, (f) => {
        if (mode === "title") f.tag().setTitle("Typed title");
        else if (mode === "clear-comment") f.tag().setComment("");
        else f.setProperties({ title: ["Replacement title"] });
      }),
    );
  }
}
// FLAC application blocks are outside the generic tag property map.
const flac = path.join(dir, "application.flac");
let b = await readFile(path.join(generated, "node-wasi", "base.flac"));
const firstEnd = 8 + b.readUIntBE(5, 3),
  marker = "RLAB-independent-application-payload";
const appBody = Buffer.from(marker),
  appHeader = Buffer.alloc(4);
appHeader[0] = 2;
appHeader.writeUIntBE(appBody.length, 1, 3);
await writeFile(
  flac,
  Buffer.concat([
    b.subarray(0, firstEnd),
    appHeader,
    appBody,
    b.subarray(firstEnd),
  ]),
);
await test(
  "flac-unmodeled-application-block",
  flac,
  () => edit(flac, (f) => f.setProperty("TITLE", "Application retained")),
  { marker },
);
// Independently populate FLAC picture geometry that the JS Picture type omits.
const geometry = Buffer.from(
  await readFile(path.join(generated, "node-" + backend, "base.flac")),
);
for (let offset = 4; offset + 4 < geometry.length;) {
  const kind = geometry[offset] & 127,
    last = geometry[offset] & 128,
    n = geometry.readUIntBE(offset + 1, 3),
    body = offset + 4;
  if (kind === 6) {
    let at = body + 4;
    const mime = geometry.readUInt32BE(at);
    at += 4 + mime;
    const desc = geometry.readUInt32BE(at);
    at += 4 + desc;
    geometry.writeUInt32BE(32, at);
    geometry.writeUInt32BE(32, at + 4);
    geometry.writeUInt32BE(24, at + 8);
  }
  offset = body + n;
  if (last) break;
}
for (const action of ["title", "replace-front"]) {
  const file = path.join(dir, "geometry-" + action + ".flac");
  await writeFile(file, geometry);
  await test("flac-picture-geometry-" + action, file, () =>
    edit(file, (f) => {
      if (action === "title") f.setProperty("TITLE", "Geometry preservation");
      else
        f.setPictures([
          ...f.getPictures().filter((p) => p.type !== "FrontCover"),
          {
            type: "FrontCover",
            mimeType: "image/jpeg",
            data: assetsJpeg,
            description: "New front",
          },
        ]);
    }),
  );
}
// Separately generated mdta atoms must not be mistaken for the usual iTunes profile.
const mdta = path.join(dir, "mdta.m4a");
ffmpeg([
  "-y",
  "-i",
  path.join(generated, "originals", "sine.m4a"),
  "-map",
  "0:a:0",
  "-c:a",
  "copy",
  "-movflags",
  "use_metadata_tags",
  "-metadata",
  "org.rhythm.lab.UNKNOWN=Independent mdta value",
  mdta,
]);
await test(
  "m4a-mdta-title",
  mdta,
  () => edit(mdta, (f) => f.setProperty("TITLE", "Edited mdta title")),
  { marker: "Independent mdta value" },
);
const unknown = path.join(dir, "m4a-unknown-property.m4a");
await copyFile(path.join(generated, `node-${backend}`, "base.m4a"), unknown);
await test(
  "m4a-unknown-property-write",
  unknown,
  () =>
    edit(unknown, (f) =>
      f.setProperty("----:org.rhythm.lab:NewCustom", "NEW_CUSTOM_VALUE"),
    ),
  { marker: "NEW_CUSTOM_VALUE" },
);
// MP4 freeform vendor/case preservation plus index-specific artwork policy.
for (const action of ["title", "replace-first", "remove-first"]) {
  const file = path.join(dir, `m4a-${action}.m4a`);
  await copyFile(path.join(generated, `node-${backend}`, "base.m4a"), file);
  const before = await independent(file);
  await test(`m4a-${action}-vendor-artwork`, file, () =>
    edit(file, (f) => {
      if (action === "title") f.setProperty("TITLE", "Vendor remains");
      else {
        const pictures = f.getPictures();
        f.setPictures(
          action === "remove-first"
            ? pictures.slice(1)
            : [
                { ...pictures[0], mimeType: "image/jpeg", data: assetsJpeg },
                ...pictures.slice(1),
              ],
        );
      }
    }),
  );
  const after = await independent(file);
  results.cases.at(-1).indexedArtwork = {
    before: before.pictures,
    after: after.pictures,
    additionalPreserved: after.pictures.some(
      (p) => p.hash === before.pictures[1]?.hash,
    ),
  };
}
await writeFile(
  path.join(generated, `edges-${backend}.json`),
  JSON.stringify(results, null, 2) + "\n",
);
